arguments.command:
cd /app && python3 -c "
import jump_analyzer as J, cv2, numpy as np
bg=None; b=[]
for i,f in enumerate(J._read_frames('example_video.mp4')):
    if i==0:
        bg=cv2.GaussianBlur(f,(5,5),0).astype(np.int16); b.append(None); continue
    s=J._foreground_stats(f,bg)
    b.append(None if s is None else s)
for i,s in enumerate(b): print(i,s)
" | sed -n '1,120p'

